  dynamicTierAttempts: array<atomic<u32>, 4>,
  dynamicTierAccepts: array<atomic<u32>, 4>,
  // Applied skip buckets: <16, 16..255, 256..4095, >=4096.
  dynamicSkipBuckets: array<atomic<u32>, 4>,
  dynamicCandidateUses: atomic<u32>,
